//! The C ABI of KittyChart. The header is `include/kittychart.h` (generated by cbindgen).
//!
//! Conventions:
//! - Functions that can fail return `0` on success and `-1` on failure. The message is then
//!   available from [`kc_last_error`] on the same thread.
//! - Options pointers may be `NULL` for defaults. Zero numeric fields and `NULL` strings also
//!   mean "default".
//! - Memory the library returns ([`kc_bytes`], and the pixels of [`kc_image`]) is freed with
//!   [`kc_bytes_free`]. Buffers are NUL-terminated (not counted in `len`), so text output can
//!   be used as a C string directly.
//! - No function panics across the boundary: an internal panic becomes an error return.

#![allow(non_camel_case_types)] // C names: kc_chart, kc_bytes …

use std::cell::RefCell;
use std::ffi::{CStr, CString, c_char, c_int};
use std::panic::{AssertUnwindSafe, catch_unwind};
use std::ptr;

use kittychart::{CellMode, ChartConfig, Color, RenderOptions};

/// A parsed chart configuration. Create with [`kc_chart_from_json`], free with
/// [`kc_chart_free`].
#[derive(Debug)]
pub struct kc_chart {
    config: ChartConfig,
}

/// Bytes owned by the library. Free with [`kc_bytes_free`].
#[repr(C)]
#[derive(Debug)]
pub struct kc_bytes {
    pub data: *mut u8,
    pub len: usize,
}

/// A rendered bitmap: `width × height` pixels of non-premultiplied RGBA8, row by row.
#[repr(C)]
#[derive(Debug)]
pub struct kc_image {
    pub width: u32,
    pub height: u32,
    pub rgba: kc_bytes,
}

/// Options for [`kc_render_png`] and [`kc_render_rgba`].
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct kc_render_options {
    /// Logical (CSS) width in pixels. 0: 800.
    pub width: f32,
    /// Logical height. 0: from `options.aspectRatio` (default 2), as Chart.js does.
    pub height: f32,
    /// Device pixel ratio; the bitmap is `width·scale × height·scale`. 0: 1.
    pub scale: f32,
    /// Any CSS color. NULL: transparent.
    pub background: *const c_char,
}

/// Options for [`kc_show`].
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct kc_show_options {
    /// "auto", "kitty", "sixel", "text", "blocks", "half" or "braille".
    /// NULL: `$KITTYCHART_PROTOCOL`, else "auto" (kitty graphics, then sixel, then text).
    pub protocol: *const c_char,
    /// Width in cells. 0: the terminal width.
    pub cols: u16,
    /// Height in cells. 0: from the chart's aspect ratio.
    pub rows: u16,
    /// Logical width/height in CSS pixels (override cols/rows). 0: unset.
    pub width: f32,
    pub height: f32,
    /// Device pixels per CSS pixel. 0: chart text about as tall as terminal text.
    pub scale: f32,
    /// Any CSS color. NULL: transparent.
    pub background: *const c_char,
    /// kitty: draw with Unicode placeholders (automatic inside tmux).
    pub placeholders: bool,
    /// Skip terminal detection.
    pub force: bool,
    /// Use Chart.js's default colors instead of the terminal theme's.
    pub chartjs_colors: bool,
}

thread_local! {
    static LAST_ERROR: RefCell<Option<CString>> = const { RefCell::new(None) };
}

fn set_error(msg: impl Into<String>) {
    let msg = msg.into().replace('\0', " ");
    LAST_ERROR.with(|e| *e.borrow_mut() = CString::new(msg).ok());
}

/// Run `f`, turning `Err` and panics into a `-1` return with [`kc_last_error`] set.
fn guard(f: impl FnOnce() -> Result<(), String>) -> c_int {
    match catch_unwind(AssertUnwindSafe(f)) {
        Ok(Ok(())) => 0,
        Ok(Err(e)) => {
            set_error(e);
            -1
        }
        Err(p) => {
            let msg = p
                .downcast_ref::<&str>()
                .map(|s| s.to_string())
                .or_else(|| p.downcast_ref::<String>().cloned())
                .unwrap_or_else(|| "unknown".into());
            set_error(format!("internal error: {msg}"));
            -1
        }
    }
}

/// # Safety
/// `s` is NULL or a valid NUL-terminated string.
unsafe fn opt_str<'a>(s: *const c_char, what: &str) -> Result<Option<&'a str>, String> {
    if s.is_null() {
        return Ok(None);
    }
    // SAFETY: non-null and NUL-terminated per the caller's contract.
    let c = unsafe { CStr::from_ptr(s) };
    c.to_str().map(Some).map_err(|_| format!("{what} is not valid UTF-8"))
}

fn color(s: Option<&str>) -> Result<Option<Color>, String> {
    s.map(|b| kittychart::parse_color(b).ok_or_else(|| format!("invalid color {b:?}"))).transpose()
}

fn positive(v: f32) -> Option<f32> {
    (v.is_finite() && v > 0.0).then_some(v)
}

fn bytes(mut v: Vec<u8>) -> kc_bytes {
    let len = v.len();
    v.push(0);
    let b = Box::into_raw(v.into_boxed_slice());
    kc_bytes { data: b.cast::<u8>(), len }
}

/// Parse a Chart.js configuration (`{"type", "data", "options"}`) from NUL-terminated UTF-8
/// JSON. Returns NULL on error (see [`kc_last_error`]).
///
/// # Safety
/// `json` is NULL or a valid NUL-terminated string.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn kc_chart_from_json(json: *const c_char) -> *mut kc_chart {
    let mut out = ptr::null_mut();
    guard(|| {
        // SAFETY: forwarded caller contract.
        let json = unsafe { opt_str(json, "json") }?.ok_or("json is NULL")?;
        let config = ChartConfig::from_json(json).map_err(|e| e.to_string())?;
        out = Box::into_raw(Box::new(kc_chart { config }));
        Ok(())
    });
    out
}

/// Replace a chart's configuration (for example with new data). On error the chart is left
/// unchanged.
///
/// # Safety
/// `chart` comes from [`kc_chart_from_json`]; `json` is NULL or a valid NUL-terminated string.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn kc_chart_set_json(chart: *mut kc_chart, json: *const c_char) -> c_int {
    guard(|| {
        // SAFETY: caller contract.
        let chart = unsafe { chart.as_mut() }.ok_or("chart is NULL")?;
        // SAFETY: caller contract.
        let json = unsafe { opt_str(json, "json") }?.ok_or("json is NULL")?;
        chart.config = ChartConfig::from_json(json).map_err(|e| e.to_string())?;
        Ok(())
    })
}

/// Free a chart. NULL is ignored.
///
/// # Safety
/// `chart` is NULL or comes from [`kc_chart_from_json`] and wasn't freed before.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn kc_chart_free(chart: *mut kc_chart) {
    if !chart.is_null() {
        // SAFETY: allocated by Box::into_raw in kc_chart_from_json.
        drop(unsafe { Box::from_raw(chart) });
    }
}

/// # Safety
/// `opts` is NULL or valid, with valid strings.
unsafe fn render_options(opts: *const kc_render_options) -> Result<RenderOptions, String> {
    // SAFETY: caller contract.
    let o = unsafe { opts.as_ref() };
    let mut r = RenderOptions::new(o.and_then(|o| positive(o.width)).unwrap_or(800.0))
        .dpr(o.and_then(|o| positive(o.scale)).unwrap_or(1.0));
    r.height = o.and_then(|o| positive(o.height));
    // SAFETY: caller contract.
    r.background = color(unsafe { opt_str(o.map_or(ptr::null(), |o| o.background), "background") }?)?;
    Ok(r)
}

/// Render to a PNG file in memory.
///
/// # Safety
/// `chart` is valid; `opts` is NULL or valid; `out` is valid for writes.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn kc_render_png(
    chart: *const kc_chart,
    opts: *const kc_render_options,
    out: *mut kc_bytes,
) -> c_int {
    guard(|| {
        // SAFETY: caller contract.
        let (chart, out) =
            unsafe { (chart.as_ref().ok_or("chart is NULL")?, out.as_mut().ok_or("out is NULL")?) };
        // SAFETY: caller contract.
        let r = unsafe { render_options(opts) }?;
        *out = bytes(kittychart::render(chart.config.clone(), &r).to_png());
        Ok(())
    })
}

/// Render to raw RGBA pixels.
///
/// # Safety
/// `chart` is valid; `opts` is NULL or valid; `out` is valid for writes.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn kc_render_rgba(
    chart: *const kc_chart,
    opts: *const kc_render_options,
    out: *mut kc_image,
) -> c_int {
    guard(|| {
        // SAFETY: caller contract.
        let (chart, out) =
            unsafe { (chart.as_ref().ok_or("chart is NULL")?, out.as_mut().ok_or("out is NULL")?) };
        // SAFETY: caller contract.
        let r = unsafe { render_options(opts) }?;
        let img = kittychart::render(chart.config.clone(), &r);
        *out = kc_image { width: img.width, height: img.height, rgba: bytes(img.rgba) };
        Ok(())
    })
}

/// Render as text: `cols × rows` terminal cells of block and Braille characters with
/// truecolor ANSI escapes, rows separated by `\r\n`. `rows` 0 follows the aspect ratio. `mode`
/// is "text" (NULL), "blocks", "half" or "braille".
///
/// # Safety
/// `chart` is valid; `mode` is NULL or a valid string; `out` is valid for writes.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn kc_render_text(
    chart: *const kc_chart,
    cols: u16,
    rows: u16,
    mode: *const c_char,
    out: *mut kc_bytes,
) -> c_int {
    guard(|| {
        // SAFETY: caller contract.
        let (chart, out) =
            unsafe { (chart.as_ref().ok_or("chart is NULL")?, out.as_mut().ok_or("out is NULL")?) };
        // SAFETY: caller contract.
        let mode = match unsafe { opt_str(mode, "mode") }?.unwrap_or("text") {
            "text" => CellMode::Auto,
            "blocks" => CellMode::Blocks,
            "half" => CellMode::HalfBlocks,
            "braille" => CellMode::Braille,
            m => return Err(format!("unknown text mode {m:?}; expected text, blocks, half or braille")),
        };
        let rows = (rows > 0).then_some(rows);
        let r = kittychart::terminal::render_cells_for_terminal(
            chart.config.clone(),
            cols.max(1),
            rows,
            mode,
            None,
        );
        *out = bytes(r.bytes);
        Ok(())
    })
}

/// Draw the chart in the terminal at the cursor, leaving the cursor below it: detects kitty
/// graphics, sixel and the terminal's colors, falling back to text. Writes to stdout, or to
/// the controlling terminal when stdout is redirected. Unix only (elsewhere it returns -1).
///
/// # Safety
/// `chart` is valid; `opts` is NULL or valid, with valid strings.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn kc_show(chart: *const kc_chart, opts: *const kc_show_options) -> c_int {
    guard(|| {
        // SAFETY: caller contract.
        let chart = unsafe { chart.as_ref() }.ok_or("chart is NULL")?;
        // SAFETY: caller contract.
        unsafe { show(chart, opts.as_ref()) }
    })
}

#[cfg(unix)]
unsafe fn show(chart: &kc_chart, o: Option<&kc_show_options>) -> Result<(), String> {
    use kittychart::show::{Mode, ShowOptions};
    let nz = |v: u16| (v > 0).then_some(v);
    let mut s = ShowOptions::default();
    if let Some(o) = o {
        // SAFETY: caller contract.
        s.mode = unsafe { opt_str(o.protocol, "protocol") }?.map(str::parse::<Mode>).transpose()?;
        s.cols = nz(o.cols);
        s.rows = nz(o.rows);
        s.width = positive(o.width);
        s.height = positive(o.height);
        s.scale = positive(o.scale);
        // SAFETY: caller contract.
        s.background = color(unsafe { opt_str(o.background, "background") }?)?;
        s.placeholders = o.placeholders;
        s.force = o.force;
        s.chartjs_colors = o.chartjs_colors;
    }
    kittychart::show::show(chart.config.clone(), &s).map(drop).map_err(|e| e.to_string())
}

#[cfg(not(unix))]
unsafe fn show(_chart: &kc_chart, _o: Option<&kc_show_options>) -> Result<(), String> {
    Err("drawing in the terminal is only supported on Unix for now; render a PNG instead".into())
}

/// Free bytes returned by the library (including `kc_image.rgba`). A NULL `data` is ignored.
///
/// # Safety
/// `b` was returned by this library and not freed before.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn kc_bytes_free(b: kc_bytes) {
    if !b.data.is_null() {
        // SAFETY: allocated by `bytes` as a boxed slice of len + 1 (the NUL).
        drop(unsafe { Box::from_raw(ptr::slice_from_raw_parts_mut(b.data, b.len + 1)) });
    }
}

/// The last error on this thread, or NULL. Valid until the next failing call on this thread.
#[unsafe(no_mangle)]
pub extern "C" fn kc_last_error() -> *const c_char {
    LAST_ERROR.with(|e| e.borrow().as_ref().map_or(ptr::null(), |c| c.as_ptr()))
}

/// The library version, e.g. "0.0.1".
#[unsafe(no_mangle)]
pub extern "C" fn kc_version() -> *const c_char {
    concat!(env!("CARGO_PKG_VERSION"), "\0").as_ptr().cast()
}
